package ama.transcript;
import ama.contract.MinutesContracts.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task10Fix01DeferredTest {
 @Test void onlyNamedOrdinaryFailuresCanYieldToWinner(){for(var code:List.of(FailureCode.ARCHIVE_IO_UNAVAILABLE,FailureCode.BUDGET_EXCEEDED))assertDoesNotThrow(()->MinutesDeferredPreparation.beforeReplay(new Failure(code)));for(var code:List.of(FailureCode.PROFILE_UNAVAILABLE,FailureCode.PROVENANCE_UNAVAILABLE,FailureCode.CAPABILITY_UNAVAILABLE,FailureCode.FINGERPRINT_MISMATCH,FailureCode.CANCELLED)){var error=new Failure(code);assertSame(error,assertThrows(Failure.class,()->MinutesDeferredPreparation.beforeReplay(error)));}var denied=new ama.access.MeetingAccess.AccessDeniedException();assertSame(denied,assertThrows(RuntimeException.class,()->MinutesDeferredPreparation.beforeReplay(denied)));var bug=new NullPointerException();assertSame(bug,assertThrows(RuntimeException.class,()->MinutesDeferredPreparation.beforeReplay(bug)));assertDoesNotThrow(()->MinutesDeferredPreparation.beforeReplay(new ama.contract.TranscriptContracts.Failure(409,"REVISION_CONFLICT")));}
 @Test void interruptionNeverBecomesSuccessfulReplay(){var ordinary=new Failure(FailureCode.ARCHIVE_IO_UNAVAILABLE);Thread.currentThread().interrupt();try{assertSame(ordinary,assertThrows(Failure.class,()->MinutesDeferredPreparation.beforeReplay(ordinary)));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
 @Test void legacyOrdinaryProtocolsRetainActualIoClassification()throws Exception{for(var entry:Map.of(JdbcSavedTranscripts.class,"ordinaryPreparationFailure",JdbcMinutesInitialSettings.class,"ordinary",JdbcMinutesGenerationCommands.class,"ordinary").entrySet()){var method=entry.getKey().getDeclaredMethod(entry.getValue(),RuntimeException.class);method.setAccessible(true);assertEquals(true,method.invoke(null,new Failure(FailureCode.ARCHIVE_IO_UNAVAILABLE)));}}
}
